func specSerialize(h Header) [HeaderSize]byte {
	var raw [HeaderSize]byte
	binary.BigEndian.PutUint16(raw[0:2], uint16(uint64(h.Id)<<0))
	binary.BigEndian.PutUint16(raw[2:4], uint16(uint64(h.Qr)<<15|uint64(h.Opcode)<<11|uint64(h.Aa)<<10|uint64(h.Tc)<<9|uint64(h.Rd)<<8|uint64(h.Ra)<<7|uint64(h.Rcode)<<0))
	binary.BigEndian.PutUint16(raw[4:6], uint16(uint64(h.Qdcount)<<0))
	binary.BigEndian.PutUint16(raw[6:8], uint16(uint64(h.Ancount)<<0))
	binary.BigEndian.PutUint16(raw[8:10], uint16(uint64(h.Nscount)<<0))
	binary.BigEndian.PutUint16(raw[10:12], uint16(uint64(h.Arcount)<<0))
	return raw
}

func pick(r *rand.Rand, lo, hi uint64) uint64 {
	switch r.IntN(4) {
	case 0:
		return lo
	case 1:
		return hi
	}
	if lo == 0 && hi == math.MaxUint64 {
		return r.Uint64()
	}
	return lo + r.Uint64N(hi-lo+1)
}

// randomHeader returns a valid header, biased towards boundary values.
func randomHeader(r *rand.Rand) Header {
	var h Header
	h.Id = uint16(pick(r, 0, 65535))
	h.Qr = uint8(pick(r, 0, 1))
	h.Opcode = uint8(pick(r, 0, 15))
	h.Aa = uint8(pick(r, 0, 1))
	h.Tc = uint8(pick(r, 0, 1))
	h.Rd = uint8(pick(r, 0, 1))
	h.Ra = uint8(pick(r, 0, 1))
	h.Rcode = uint8(pick(r, 0, 15))
	h.Qdcount = uint16(pick(r, 0, 65535))
	h.Ancount = uint16(pick(r, 0, 65535))
	h.Nscount = uint16(pick(r, 0, 65535))
	h.Arcount = uint16(pick(r, 0, 65535))
	return h
}

// anyHeader returns arbitrary field values, mostly invalid ones near the limits.
func anyHeader(r *rand.Rand) Header {
	var h Header
	h.Id = uint16(pick(r, 0, 65535))
	h.Qr = uint8(pick(r, 0, 255))
	h.Opcode = uint8(pick(r, 0, 255))
	h.Aa = uint8(pick(r, 0, 255))
	h.Tc = uint8(pick(r, 0, 255))
	h.Rd = uint8(pick(r, 0, 255))
	h.Ra = uint8(pick(r, 0, 255))
	h.Rcode = uint8(pick(r, 0, 255))
	h.Qdcount = uint16(pick(r, 0, 65535))
	h.Ancount = uint16(pick(r, 0, 65535))
	h.Nscount = uint16(pick(r, 0, 65535))
	h.Arcount = uint16(pick(r, 0, 65535))
	return h
}

func reasonOf(t *testing.T, err error) Reason {
	t.Helper()
	if err == nil {
		return 0
	}
	var e *Error
	if !errors.As(err, &e) {
		t.Fatalf("unexpected error type %T: %v", err, err)
	}
	return e.Reason
}

// inputs yields valid encodings, single-bit mutations of them and random bytes.
func inputs(r *rand.Rand, n int, yield func(data []byte)) {
	for i := 0; i < n; i++ {
		raw := specSerialize(randomHeader(r))
		data := raw[:]
		switch i % 4 {
		case 1:
			bit := r.IntN(8 * HeaderSize)
			data[bit/8] ^= 1 << (bit % 8)
		case 2:
			for j := range data {
				data[j] = byte(r.Uint32())
			}
		case 3:
			data[r.IntN(HeaderSize)] = byte(r.Uint32())
		}
		yield(append([]byte(nil), data...))
	}
}

func TestRoundTripValidHeaders(t *testing.T) {
	r := rand.New(rand.NewPCG(1, 3))
	for i := 0; i < 5000; i++ {
		h := randomHeader(r)
		if err := Validate(h); err != nil {
			t.Fatalf("Validate(%+v) = %v", h, err)
		}
		if reason := specValidate(h); reason != 0 {
			t.Fatalf("specValidate(%+v) = %v", h, reason)
		}
		enc, err := AppendSerialize(nil, h)
		if err != nil {
			t.Fatalf("AppendSerialize(%+v): %v", h, err)
		}
		if want := specSerialize(h); !bytes.Equal(enc, want[:]) {
			t.Fatalf("AppendSerialize(%+v) = %x, spec says %x", h, enc, want)
		}
		data := enc
		got, n, err := Parse(data)
		if err != nil || got != h {
			t.Fatalf("Parse(%x) = %+v, %v; want %+v", data, got, err, h)
		}
		if n != HeaderSize {
			t.Fatalf("Parse(%x) consumed %d, want %d", data, n, HeaderSize)
		}
	}
}

func TestParseMatchesSpec(t *testing.T) {
	r := rand.New(rand.NewPCG(2, 3))
	inputs(r, 20000, func(data []byte) {
		want, wantReason := specParse(data)
		got, reason := parseHeaderOnly(t, data)
		if reason != wantReason || got != want {
			t.Fatalf("Parse(%x) = %+v, %v; spec says %+v, %v", data, got, reason, want, wantReason)
		}
		if reason != 0 {
			return
		}
		enc, err := AppendSerialize(nil, got)
		if err != nil || !bytes.Equal(enc, data[:HeaderSize]) {
			t.Fatalf("serialize(parse(%x)) = %x, %v", data, enc, err)
		}
	})
}

// parseHeaderOnly parses data and reports the header decision alone.
func parseHeaderOnly(t *testing.T, data []byte) (Header, Reason) {
	t.Helper()
	got, n, err := Parse(data)
	reason := reasonOf(t, err)
	if reason == 0 && n != HeaderSize {
		t.Fatalf("Parse(%x) consumed %d", data, n)
	}
	return got, reason
}

func TestValidateMatchesSpec(t *testing.T) {
	r := rand.New(rand.NewPCG(3, 3))
	for i := 0; i < 20000; i++ {
		h := anyHeader(r)
		if i%2 == 0 {
			h = randomHeader(r)
		}
		got := reasonOf(t, Validate(h))
		if want := specValidate(h); got != want {
			t.Fatalf("Validate(%+v) = %v, spec says %v", h, got, want)
		}
		dst := make([]byte, 3, 64)
		copy(dst[:cap(dst)], bytes.Repeat([]byte{0x5a}, cap(dst)))
		out, err := AppendSerialize(dst, h)
		if got != 0 {
			if err == nil || len(out) != 3 || !bytes.Equal(dst[:cap(dst)], bytes.Repeat([]byte{0x5a}, cap(dst))) {
				t.Fatalf("AppendSerialize(invalid %+v) = %x, %v; or wrote to dst", h, out, err)
			}
		} else if err != nil || !bytes.Equal(out[:3], []byte{0x5a, 0x5a, 0x5a}) {
			t.Fatalf("AppendSerialize(%+v) = %x, %v", h, out, err)
		}
	}
}

func TestTruncatedInput(t *testing.T) {
	raw := specSerialize(randomHeader(rand.New(rand.NewPCG(4, 4))))
	for size := 0; size < HeaderSize; size++ {
		data := raw[:size]
		got, n, err := Parse(data)
		var e *Error
		if !errors.As(err, &e) || e.Reason != ReasonTruncated || e.Missing != uint64(HeaderSize-size) ||
			!errors.Is(err, io.ErrUnexpectedEOF) || n != 0 || got != (Header{}) {
			t.Fatalf("Parse(%d bytes) = %+v, %d, %v", size, got, n, err)
		}
	}
}

func TestReferenceDecoders(t *testing.T) {
	if len(referenceDecoders) == 0 {
		t.Skip("no hand-written reference decoder registered for this format")
	}
	r := rand.New(rand.NewPCG(5, 3))
	inputs(r, 20000, func(data []byte) {
		got, reason := parseHeaderOnly(t, data)
		for _, ref := range referenceDecoders {
			want, ok := ref.decode(data)
			if ok != (reason == 0) || (ok && want != got) {
				t.Fatalf("%s: decode(%x) = %+v, %v; Parse gives %+v, %v", ref.name, data, want, ok, got, reason)
			}
		}
	})
}

func FuzzParse(f *testing.F) {
	r := rand.New(rand.NewPCG(6, 3))
	for i := 0; i < 8; i++ {
		raw := specSerialize(randomHeader(r))
		f.Add(raw[:])
	}
	f.Add([]byte{})
	f.Add(bytes.Repeat([]byte{0xff}, HeaderSize+3))
	f.Fuzz(func(t *testing.T, data []byte) {
		before := append([]byte(nil), data...)
		got, reason := parseHeaderOnly(t, data)
		if !bytes.Equal(before, data) {
			t.Fatal("Parse modified its input")
		}
		want, wantReason := specParse(data)
		if reason != wantReason || got != want {
			t.Fatalf("Parse(%x) = %+v, %v; spec says %+v, %v", data, got, reason, want, wantReason)
		}
		if reason == 0 {
			enc, err := AppendSerialize(nil, got)
			if err != nil || !bytes.Equal(enc, data[:HeaderSize]) {
				t.Fatalf("serialize(parse(%x)) = %x, %v", data, enc, err)
			}
		}
	})
}

func FuzzRoundTrip(f *testing.F) {
	f.Add(uint64(0), uint64(0))
	f.Add(uint64(1), uint64(math.MaxUint64))
	f.Fuzz(func(t *testing.T, a, b uint64) {
		r := rand.New(rand.NewPCG(a, b))
		h := randomHeader(r)
		enc, err := AppendSerialize(nil, h)
		if err != nil {
			t.Fatalf("AppendSerialize(%+v): %v", h, err)
		}
		got, reason := parseHeaderOnly(t, enc)
		if reason != 0 || got != h {
			t.Fatalf("Parse(AppendSerialize(%+v)) = %+v, %v", h, got, reason)
		}
	})
}
